    )
    case setInterfaceIfac(address: String, ifac: IfacConfig
    )
    case createIdentity(name: String
    )
    case importIdentity(name: String, hex: String
    )
    case importIdentityFile(name: String, path: String
    )
    case exportIdentity(address: String, path: String
    )
    case activateIdentity(address: String
    )
    case removeIdentity(address: String
    )
    case setKeychainBridge
    case createDestination(appName: String, aspect: String
    )
    case loadDestination(identityHex: String, appName: String, aspect: String
    )
    case announce(destinationHash: String, appData: Data
    )
    case requestPath(destinationHash: String
    )
    case dropPath(destinationHash: String
    )
    case markPathUnresponsive(destinationHash: String
    )
    case markPathResponsive(destinationHash: String
    )
    case openLink(destinationHash: String
    )
    case closeLink(destinationHash: String
    )
    case sendData(destinationHash: String, data: Data
    )
    case sendRequest(destinationHash: String, path: String, data: Data, timeoutMs: UInt64
    )
    case registerRequestHandler(destinationHash: String, path: String
    )
    case sendResponse(requestId: String, data: Data
    )
    case getCapabilities
    case setLogBridge
    case setTransportBridge
    case startNetworkTick(intervalMs: UInt64
    )
    case stopNetworkTick
    case setLxmfDeliveryIdentity(config: LxmfDeliveryConfig
    )
    case announceLxmfDelivery
    case announceLxmfPropagationNode
    case sendLxmfMessage(destinationHash: String, fields: LxmfMessageFields, method: LxmfDeliveryMethod, stampCost: UInt8?, includeTicket: Bool, transportEncryption: String?
    )
    case ingestLxmUri(uri: String
    )
