// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum AppUpdate: Equatable, Hashable {
    
    case fullState(AppState
    )
    case nodeStatus(NodeStatus
    )
    case networkTick(NetworkTick
    )
    case backendCapabilities(BackendCapabilities
    )
    case log(level: LogLevel, message: String
    )
    case toast(String
    )
    case announceReceived(addressHash: String, nameHashHex: String, appData: Data, hops: UInt8?
    )
    case interfaceAdded(address: String, name: String, kind: String
    )
    case interfaceRemoved(address: String
    )
    case interfaceUpdated(address: String, online: Bool, failed: Bool
    )
    case pathResolved(destinationHash: String, hops: UInt8
    )
    case pathLost(destinationHash: String
    )
    case linkOpened(linkId: String, destinationHash: String
    )
    case linkActivated(linkId: String, destinationHash: String
    )
    case linkData(linkId: String, data: Data
    )
    case linkClosed(linkId: String
    )
    case dataReceived(destinationHash: String, data: Data
    )
    case requestReceived(requestId: String, destinationHash: String, path: String, data: Data
    )
    case responseReceived(requestId: String, data: Data
    )
    case requestFailed(requestId: String
    )
    case identityCreated(addressHash: String
    )
    case knownDestinationUpdated(destinationHash: String
    )
    case messageReceived(hash: String, sourceHash: String, destinationHash: String
    )
    case messageStateChanged(hash: String, state: String, progress: Double
    )
    case messageDuplicate(hash: String
    )
    case deliveryReceipt(hash: String
    )
    case sendFailed(hash: String, reason: String
    )
    case paperMessagePacked(hash: String, uri: String
    )
    case propagationTransferChanged(state: String, progress: Double, size: UInt64
    )
    case callStateChanged(callId: String, state: String
    )
    case incomingCall(callId: String, destinationHash: String
    )
    case callFrames(callId: String, codec: String, data: Data
    )
    case callClosed(callId: String
    )
    case audioWarning(callId: String, message: String
    )
    case resourceProgress(hash: String, status: String, progress: Double
    )
    case resourceComplete(hash: String, data: Data?, metadata: Data?
    )
    case resourceFailed(hash: String
    )
    case discoveryUpdated(interfaces: [DiscoveredInterfaceSummary]
    )
    case sharedInstanceClientConnected(address: String
    )
    case sharedInstanceClientDisconnected(address: String
    )





}

