private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_reticulum_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_dispatch() != 31130) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_listen_for_updates() != 4790) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_set_audio_bridge() != 42460) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_set_keychain_bridge() != 23368) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_set_log_bridge() != 29407) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_set_transport_bridge() != 1465) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_state() != 47885) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_ffiapp_stop_listening() != 33065) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_constructor_ffiapp_new() != 50634) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_appreconciler_reconcile() != 45131) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_audiobridge_read_frames() != 2407) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_audiobridge_write_frames() != 60096) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_keychainbridge_encrypt() != 2544) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_keychainbridge_decrypt() != 1399) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_logbridge_log() != 32849) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_transportbridge_mtu() != 59439) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_transportbridge_read_chunk() != 33598) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reticulum_ffi_checksum_method_transportbridge_write_chunk() != 58660) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitAppReconciler()
    uniffiCallbackInitAudioBridge()
    uniffiCallbackInitKeychainBridge()
    uniffiCallbackInitLogBridge()
    uniffiCallbackInitTransportBridge()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureReticulumFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

